import React, { useState, useEffect } from "react";
import { fetchBudget, updateBudget } from "../../utils/budget-utils";
import { AppContext } from "../../context/AppContext";


const Budget = () => {
    const { expenses } = useContext(AppContext);
    const [budget, setBudget] = useState<number>(0);
    const [isEditing, setIsEditing] = useState(false);
    const [newBudget, setNewBudget] = useState<number>(budget);
    const [remaining, setRemaining] = useState<number>(0);

  
    useEffect(() => {
      const loadBudget = async () => {
        try {
          const fetchedBudget = await fetchBudget();
          setBudget(fetchedBudget);
        } catch (error) {
          console.error("Failed to load budget:", error);
        }
      };
  
      loadBudget();
    }, []);

    useEffect(() => {
      // Calculate remaining amount when budget or expenses change
      const totalExpenses = expenses.reduce((total, expense) => total + expense.cost, 0);
      setRemaining(budget - totalExpenses);
    }, [budget, expenses]); // Re-run when budget or expenses change

    const handleSave = async () => {
      try {
        const updatedBudget = await updateBudget(newBudget);
        setBudget(updatedBudget);
        setIsEditing(false);
      } catch (error) {
        console.error("Failed to update budget:", error);
      }
    };
    
    return (
      <div className="alert alert-secondary p-3 d-flex align-items-center justify-content-between">
        {isEditing ? (
          <div>
            <input
              type="number"
              value={newBudget}
              onChange={(e) => setNewBudget(Number(e.target.value))}
              className="form-control"
            />
            <button onClick={handleSave} className="btn btn-primary ms-2">Save</button>
          </div>
        ) : (
          <div>
            <span>Budget: ${budget}</span>
            <button onClick={() => setIsEditing(true)} className="btn btn-secondary ms-2">Edit</button>
          </div>
        )}
      </div>
    );
  };


export default Budget;
